from ...data_transfers.lte_data_transfer import LteDataTransfer


class DemoDataTransfer(LteDataTransfer):
    """Object responsible for managing IPHY data transfer."""

    def __init__(self, *args, **kwargs):
        """

        :param args:
        :param kwargs:
        """
        super().__init__(*args, **kwargs)
        self.logger.info(f'"{self.name}" instance of DemoDataTransfer created: ')
        self._is_running = False

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self._is_running = True
        self.logger.info(f'Dt "{self.name}": start')

    def stop(self):
        """
        Stops already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        self._is_running = False
        self.logger.info(f'Dt "{self.name}": stop')

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        return self._is_running

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="iperf"):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()' if data transfer is already finished
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: Kbits/sec
        """
        raise NotImplementedError
